En utilisait la librairie de base "os", on peut savoir quelle taille fait un fichier. En passant sur tous les dossiers on trouvera, avec un filtre, ceux qui sont de taille en Gb plus que le minimum entré.
Voici un exemple : 
import os
def list_large_folders(path, min_size_gb=1):
    for folder, subfolders, files in os.walk(path):
        folder_size = sum(os.path.getsize(os.path.join(folder, file)) for file in files)
        if folder_size >= min_size_gb * 1024**3:
            print(f"{folder}: {folder_size / 1024**3:.2f} GB")

list_large_folders("/")

